package com.empcontrol.agent;
import com.empcontrol.agent.command.EmpControlCommand; import com.empcontrol.agent.config.SecureStore; import com.empcontrol.agent.listener.*; import com.empcontrol.agent.metrics.MetricsCollector; import com.empcontrol.agent.net.AgentClient; import org.bukkit.Bukkit; import org.bukkit.command.PluginCommand; import org.bukkit.plugin.java.JavaPlugin;
public final class EMPControlAgentPlugin extends JavaPlugin { private AgentClient client; private MetricsCollector metrics;
  public void onEnable(){ SecureStore store=new SecureStore(getDataFolder().toPath()); client=new AgentClient(this); metrics=new MetricsCollector(this); SecurityListener security=new SecurityListener(this, client); getServer().getPluginManager().registerEvents(security,this); getServer().getPluginManager().registerEvents(new PlayerStatsListener(metrics, client),this); PluginCommand command=getCommand("empcontrol"); if(command!=null){ EmpControlCommand exec=new EmpControlCommand(client, store, security); command.setExecutor(exec); command.setTabCompleter(exec); } store.load().ifPresent(client::connect); Bukkit.getScheduler().runTaskTimerAsynchronously(this, () -> client.send("heartbeat", metrics.snapshot(client.connected(), client.reconnects(), client.queueSize(), client.failed())), 100L, 100L); Bukkit.getScheduler().runTaskTimerAsynchronously(this, () -> client.send("metrics", metrics.snapshot(client.connected(), client.reconnects(), client.queueSize(), client.failed())), 20L*30, 20L*30); getLogger().info("EMP Control Agent enabled. Use /empcontrol link <token> to pair."); }
  public void onDisable(){ if(client!=null) client.send("consoleLog", java.util.Map.of("level","INFO","source","plugin","category","PLUGIN","message","EMPControlAgent disabled")); }
}
